    Route::get('candidates/{candidate}/documents/{document}/download', [CandidateDocumentController::class, 'download'])->middleware('permission:candidate.view')->name('api.candidates.documents.download');
    Route::get('candidates/{candidate}/documents/{document}/preview', [CandidateDocumentController::class, 'preview'])->middleware('permission:candidate.view')->name('api.candidates.documents.preview');
    Route::patch('candidates/{candidate}/documents/{document}', [CandidateDocumentController::class, 'update'])->middleware('permission:candidate.edit')->name('api.candidates.documents.update');
    Route::delete('candidates/{candidate}/documents/{document}', [CandidateDocumentController::class, 'destroy'])->middleware('permission:candidate.delete')->name('api.candidates.documents.destroy');
