    Route::post('opportunities/import', [OpportunityImportController::class, 'import'])->middleware('permission:opportunity.create')->name('api.opportunities.import.store');
    Route::get('opportunities/{opportunity}', [OpportunityController::class, 'show'])->middleware('permission:opportunity.view')->name('api.opportunities.show');
    Route::put('opportunities/{opportunity}', [OpportunityController::class, 'update'])->middleware('permission:opportunity.edit')->name('api.opportunities.update');
    Route::delete('opportunities/{opportunity}', [OpportunityController::class, 'destroy'])->middleware('permission:opportunity.delete')->name('api.opportunities.destroy');
