    Route::post('universities', [UniversityController::class, 'store'])->middleware('permission:opportunity.create')->name('api.universities.store');
    Route::get('universities/import/template', [UniversityImportController::class, 'template'])->middleware('permission:opportunity.create')->name('api.universities.import.template');
    Route::post('universities/import', [UniversityImportController::class, 'import'])->middleware('permission:opportunity.create')->name('api.universities.import.store');
