    Route::put('universities/{university}', [UniversityController::class, 'update'])->middleware('permission:opportunity.edit')->name('api.universities.update');
    Route::delete('universities/{university}', [UniversityController::class, 'destroy'])->middleware('permission:opportunity.delete')->name('api.universities.destroy');
